INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000001'::uuid, '00000002-0000-4000-8000-000000000005'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000001'::uuid, 'en'::content_language, 'Jaipur desk rehearses a weekend haat timetable', 'A fictional municipal drill in Jaipur’s old city tested stall layout, waste sorting, and a clear walking lane for a sample weekend market.', 'The sample city desk followed volunteers as they marked chalk boxes for pottery, millet snacks, and a book stall. A supervisor timed how long it took to open a two-metre walking lane after a pretend crowd surge.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000001'::uuid, 'hi'::content_language, 'जयपुर डेस्क ने सप्ताहांत हाट की समय-सारणी का अभ्यास किया', 'जयपुर के पुराने शहर में एक काल्पनिक नगर अभ्यास ने नमूना सप्ताहांत हाट के लिए स्टॉल, कचरा पृथक्करण और पैदल मार्ग जाँचा।', 'नमूना शहर डेस्क ने स्वयंसेवकों को मिट्टी के बर्तन, बाजरे के नाश्ते और पुस्तक स्टॉल के लिए खड़िया के खाने बनाते देखा। एक पर्यवेक्षक ने भीड़ के नाटक के बाद दो मीटर का रास्ता खुलने का समय नोट किया।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000002'::uuid, 'published'::article_status, 'local'::coverage_level, 'Maharashtra', 'Pune', 'पुणे', 'Deccan', '00000002-0000-4000-8000-000000000007'::uuid, ARRAY['pune', 'libraries', 'students']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Pune sample library tests one extra reading hour', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: पुणे के नमूना पुस्तकालय ने एक अतिरिक्त पठन घंटे की जाँच की', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 1820, '2026-10-24T04:30:00.000Z'::timestamptz, '2026-10-22T04:30:00.000Z'::timestamptz, '2026-10-24T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000002'::uuid, '00000002-0000-4000-8000-000000000007'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000002'::uuid, 'en'::content_language, 'Pune sample library tests one extra reading hour', 'Librarians in a fictional Pune branch kept the reading room open for one extra sample hour and counted how many students stayed for exam notes.', 'The branch used paper tokens instead of a new membership system. Volunteers recorded noise, empty chairs, and whether the reference desk could still close the shutters safely.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000002'::uuid, 'hi'::content_language, 'पुणे के नमूना पुस्तकालय ने एक अतिरिक्त पठन घंटे की जाँच की', 'काल्पनिक पुणे शाखा के पुस्तकालयाध्यक्षों ने वाचनालय एक नमूना घंटे और खुला रखा और देखा कि कितने विद्यार्थी परीक्षा नोट्स के लिए रुके।', 'शाखा ने नई सदस्यता प्रणाली के बजाय कागज़ी टोकन इस्तेमाल किए। स्वयंसेवकों ने शोर, खाली कुर्सियाँ और यह नोट किया कि संदर्भ डेस्क शटर सुरक्षित बंद कर सकती है या नहीं।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000003'::uuid, 'published'::article_status, 'local'::coverage_level, 'Kerala', 'Kochi', 'कोच्चि', 'Fort Kochi', '00000002-0000-4000-8000-000000000006'::uuid, ARRAY['kochi', 'ferry', 'water']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1596176530529-78163a4f7af2?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Kochi sample desk corrects a ferry rehearsal note', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: कोच्चि नमूना डेस्क ने नौका अभ्यास नोट सुधारा', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, 'An earlier demo sentence named the wrong classroom jetty. This sample now names the Fort Kochi model only.', 'डेमो का एक पहले वाला वाक्य गलत कक्षा-घाट बताता था। यह नमूना अब केवल फोर्ट कोच्चि मॉडल का नाम लेता है।', '2026-10-23T04:30:00.000Z'::timestamptz, NULL, 960, '2026-10-23T04:30:00.000Z'::timestamptz, '2026-10-21T04:30:00.000Z'::timestamptz, '2026-10-23T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000003'::uuid, '00000002-0000-4000-8000-000000000006'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000003'::uuid, 'en'::content_language, 'Kochi sample desk corrects a ferry rehearsal note', 'A fictional Kochi ferry rehearsal checked life-jacket counts. An earlier demo sentence misstated the jetty name and is corrected below.', 'Volunteers walked a marked gangway and logged how long a sample group of twenty needed to board. The count was a stopwatch exercise beside a classroom model, not a working jetty.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000003'::uuid, 'hi'::content_language, 'कोच्चि नमूना डेस्क ने नौका अभ्यास नोट सुधारा', 'काल्पनिक कोच्चि नौका अभ्यास में लाइफ जैकेट गिने गए। डेमो का एक पहले वाला वाक्य घाट का नाम गलत बताता था, जिसे नीचे सुधारा गया है।', 'स्वयंसेवकों ने चिह्नित गैंगवे पर चलकर देखा कि बीस लोगों का नमूना समूह चढ़ने में कितना समय लेता है। गिनती एक कक्षा मॉडल के पास स्टॉपवॉच अभ्यास थी, काम करने वाला घाट नहीं।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000004'::uuid, 'published'::article_status, 'local'::coverage_level, 'Uttar Pradesh', 'Lucknow', 'लखनऊ', 'Hazratganj', '00000002-0000-4000-8000-000000000008'::uuid, ARRAY['lucknow', 'food', 'health']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Lucknow sample squad walks a food-safety checklist', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: लखनऊ की नमूना टीम ने खाद्य-सुरक्षा सूची जाँची', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 1660, '2026-10-24T04:30:00.000Z'::timestamptz, '2026-10-22T04:30:00.000Z'::timestamptz, '2026-10-24T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000004'::uuid, '00000002-0000-4000-8000-000000000008'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000004'::uuid, 'en'::content_language, 'Lucknow sample squad walks a food-safety checklist', 'A fictional evening drill in Lucknow asked demo vendors to show hand-wash water, covered trays, and a temperature card for a classroom kitchen.', 'The checklist fitted on one page. Participants scored themselves and then swapped sheets so a second pair could look for missed items such as a soap dish or a clean cloth.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000004'::uuid, 'hi'::content_language, 'लखनऊ की नमूना टीम ने खाद्य-सुरक्षा सूची जाँची', 'लखनऊ में एक काल्पनिक सायंकालीन अभ्यास में डेमो विक्रेताओं से हाथ धोने का पानी, ढके बर्तन और कक्षा रसोई का तापमान कार्ड माँगा गया।', 'जाँच सूची एक पृष्ठ में समाई। प्रतिभागियों ने स्वयं अंक दिए और फिर पन्ने बदले ताकि दूसरी जोड़ी साबुन की तश्तरी या साफ कपड़ा जैसी छूटी बातें देख सके।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000005'::uuid, 'published'::article_status, 'local'::coverage_level, 'Madhya Pradesh', 'Indore', 'इंदौर', 'Rajwada', '00000002-0000-4000-8000-000000000006'::uuid, ARRAY['indore', 'parks', 'waste']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Indore volunteers sort a sample park cleanup', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: इंदौर के स्वयंसेवकों ने नमूना पार्क सफाई छाँटी', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 740, '2026-10-22T04:30:00.000Z'::timestamptz, '2026-10-20T04:30:00.000Z'::timestamptz, '2026-10-22T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000005'::uuid, '00000002-0000-4000-8000-000000000006'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000005'::uuid, 'en'::content_language, 'Indore volunteers sort a sample park cleanup', 'A fictional Saturday circle in Indore separated paper, glass, and garden clippings during a timed park-cleanup rehearsal.', 'Children labelled three cloth bags and raced a fifteen-minute clock. The winning team was the one that left the path clear, not the one that collected the largest pile.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000005'::uuid, 'hi'::content_language, 'इंदौर के स्वयंसेवकों ने नमूना पार्क सफाई छाँटी', 'इंदौर में एक काल्पनिक शनिवार समूह ने समयबद्ध पार्क-सफाई अभ्यास में कागज, काँच और बगीचे की कतरन अलग की।', 'बच्चों ने तीन कपड़े के थैले चिह्नित किए और पंद्रह मिनट की घड़ी से दौड़ लगाई। जीत उस टीम की हुई जिसने रास्ता साफ छोड़ा, न कि सबसे बड़ा ढेर बनाने वाली टीम की।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000006'::uuid, 'published'::article_status, 'local'::coverage_level, 'Gujarat', 'Surat', 'सूरत', 'Ring Road', '00000002-0000-4000-8000-000000000002'::uuid, ARRAY['surat', 'textiles', 'design']::text[], '00000001-0000-4000-8000-000000000002'::uuid, 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Surat sample fair hangs a student textile wall', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: सूरत के नमूना मेले में विद्यार्थियों की कपड़ा दीवार टँगी', '[{"url":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&h=900&q=80","altEn":"Sample gallery image 1 for Surat sample fair hangs a student textile wall","altHi":"नमूना गैलरी चित्र 1"},{"url":"https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1400&h=900&q=80","altEn":"Sample gallery image 2 for Surat sample fair hangs a student textile wall","altHi":"नमूना गैलरी चित्र 2"}]'::jsonb, true, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 2140, '2026-10-25T04:30:00.000Z'::timestamptz, '2026-10-23T04:30:00.000Z'::timestamptz, '2026-10-25T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000006'::uuid, '00000002-0000-4000-8000-000000000002'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000006'::uuid, 'en'::content_language, 'Surat sample fair hangs a student textile wall', 'Design students in a fictional Surat studio pinned sample swatches, price cards, and repair notes for a one-evening classroom fair.', 'Buyers in the exercise were other students with paper tokens. They had to explain why a stitch could be repaired before they were allowed to “reserve” a swatch.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000006'::uuid, 'hi'::content_language, 'सूरत के नमूना मेले में विद्यार्थियों की कपड़ा दीवार टँगी', 'काल्पनिक सूरत स्टूडियो में डिज़ाइन विद्यार्थियों ने एक शाम के कक्षा मेले के लिए नमूना कपड़े, मूल्य कार्ड और मरम्मत नोट टाँगे।', 'अभ्यास के खरीदार कागज़ी टोकन वाले दूसरे विद्यार्थी थे। किसी नमूने को “आरक्षित” करने से पहले उन्हें बताना था कि टाँका कैसे सुधारा जा सकता है।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000007'::uuid, 'published'::article_status, 'local'::coverage_level, 'Madhya Pradesh', 'Bhopal', 'भोपाल', 'Upper Lake', '00000002-0000-4000-8000-000000000010'::uuid, ARRAY['bhopal', 'lake', 'science']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Bhopal students log a classroom lake sample', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: भोपाल के विद्यार्थियों ने कक्षा की झील का नमूना दर्ज किया', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 640, '2026-10-21T04:30:00.000Z'::timestamptz, '2026-10-19T04:30:00.000Z'::timestamptz, '2026-10-21T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000007'::uuid, '00000002-0000-4000-8000-000000000010'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000007'::uuid, 'en'::content_language, 'Bhopal students log a classroom lake sample', 'A fictional science circle in Bhopal recorded clarity, temperature, and bird counts from a tank of water labelled as a lake model.', 'Each pair used the same plastic secchi disc and wrote the reading twice so a classmate could check the number. The bird count came from pictures on cards, not from a shoreline census.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000007'::uuid, 'hi'::content_language, 'भोपाल के विद्यार्थियों ने कक्षा की झील का नमूना दर्ज किया', 'भोपाल के एक काल्पनिक विज्ञान समूह ने झील मॉडल कहे गए पानी के टैंक से स्पष्टता, तापमान और पक्षी गिनती दर्ज की।', 'हर जोड़ी ने एक ही प्लास्टिक डिस्क से पढ़कर संख्या दो बार लिखी ताकि साथी जाँच कर सके। पक्षी गिनती कार्डों की तस्वीरों से हुई, किसी किनारे की गणना से नहीं।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000008'::uuid, 'published'::article_status, 'state'::coverage_level, 'Rajasthan', 'Jodhpur', 'जोधपुर', NULL, '00000002-0000-4000-8000-000000000006'::uuid, ARRAY['rajasthan', 'solar', 'schools']::text[], '00000001-0000-4000-8000-000000000002'::uuid, 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=1600&h=900&q=80', 'Sample photo used with the demonstration story: Rajasthan sample schools compare rooftop shade plans', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: राजस्थान के नमूना स्कूलों ने छत की छाया योजनाएँ तुलना कीं', '[]'::jsonb, true, false, 25, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 3280, '2026-10-25T04:30:00.000Z'::timestamptz, '2026-10-23T04:30:00.000Z'::timestamptz, '2026-10-25T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000008'::uuid, '00000002-0000-4000-8000-000000000006'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000008'::uuid, 'en'::content_language, 'Rajasthan sample schools compare rooftop shade plans', 'Three fictional school clubs in Rajasthan compared paper models of shaded roofs and a single classroom solar lamp.', 'The clubs scored each plan on heat, cost written in play money, and whether students could still fly a kite on the sample terrace. A teacher kept the lamp unplugged from any real grid.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000008'::uuid, 'hi'::content_language, 'राजस्थान के नमूना स्कूलों ने छत की छाया योजनाएँ तुलना कीं', 'राजस्थान के तीन काल्पनिक विद्यालय क्लबों ने छायादार छतों के कागज़ी मॉडल और एक कक्षा सौर लैंप की तुलना की।', 'क्लबों ने हर योजना को गर्मी, खेल के पैसों में लागत, और इस बात पर अंक दिए कि नमूना छत पर पतंग उड़ सकती है या नहीं। शिक्षक ने लैंप को किसी वास्तविक ग्रिड से नहीं जोड़ा।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000009'::uuid, 'published'::article_status, 'state'::coverage_level, 'Kerala', 'Alappuzha', 'अलप्पुझा', NULL, '00000002-0000-4000-8000-000000000006'::uuid, ARRAY['kerala', 'backwaters', 'boats']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1596176530529-78163a4f7af2?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Kerala sample boat club practises a quiet hour', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: केरल के नमूना नाव क्लब ने शांत घंटे का अभ्यास किया', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 1100, '2026-10-23T04:30:00.000Z'::timestamptz, '2026-10-21T04:30:00.000Z'::timestamptz, '2026-10-23T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000009'::uuid, '00000002-0000-4000-8000-000000000006'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000009'::uuid, 'en'::content_language, 'Kerala sample boat club practises a quiet hour', 'A fictional backwater club in Kerala rehearsed an hour with engines off, using oars and a wildlife checklist on a classroom canal map.', 'Rowers called out bridge numbers from the map and noted where a sample heron card had been pinned. The exercise measured chatter, not water quality.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000009'::uuid, 'hi'::content_language, 'केरल के नमूना नाव क्लब ने शांत घंटे का अभ्यास किया', 'केरल के एक काल्पनिक बैकवाटर क्लब ने इंजन बंद रखकर चप्पुओं और कक्षा के नहर मानचित्र पर वन्य जीव सूची के साथ एक घंटे का अभ्यास किया।', 'नाविकों ने मानचित्र से पुलों के नंबर पुकारे और नोट किया कि नमूना बगुला कार्ड कहाँ टँगा था। अभ्यास ने शोर मापा, पानी की गुणवत्ता नहीं।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000010'::uuid, 'published'::article_status, 'state'::coverage_level, 'Maharashtra', 'Nashik', 'नाशिक', NULL, '00000002-0000-4000-8000-000000000009'::uuid, ARRAY['maharashtra', 'harvest', 'millet']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1625246333195-78d9c38ad449?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Maharashtra sample farms preview a millet table', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: महाराष्ट्र के नमूना खेतों ने बाजरे की मेज़ दिखाई', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 980, '2026-10-22T04:30:00.000Z'::timestamptz, '2026-10-20T04:30:00.000Z'::timestamptz, '2026-10-22T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000010'::uuid, '00000002-0000-4000-8000-000000000009'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000010'::uuid, 'en'::content_language, 'Maharashtra sample farms preview a millet table', 'A fictional Nashik classroom farm laid out millet, sorghum, and a hand-written moisture chart for a state harvest preview.', 'Students shook jars of grain and matched the sound to a chart rather than publishing a price. A visitor book asked which grain they would cook first in the demo kitchen.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000010'::uuid, 'hi'::content_language, 'महाराष्ट्र के नमूना खेतों ने बाजरे की मेज़ दिखाई', 'नाशिक के एक काल्पनिक कक्षा-खेत में राज्य फसल झलक के लिए बाजरा, ज्वार और हाथ से लिखी नमी सारणी रखी गई।', 'विद्यार्थियों ने अनाज के जार हिलाकर आवाज़ को सारणी से मिलाया, कोई भाव जारी नहीं किया। अतिथि पुस्तिका ने पूछा कि डेमो रसोई में वे कौन सा अनाज पहले पकाएँगे।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000011'::uuid, 'published'::article_status, 'state'::coverage_level, 'Tamil Nadu', 'Madurai', 'मदुरै', NULL, '00000002-0000-4000-8000-000000000007'::uuid, ARRAY['tamil-nadu', 'libraries', 'reading']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Tamil Nadu sample libraries share one story crate', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: तमिलनाडु के नमूना पुस्तकालयों ने एक कहानी पेटी बाँटी', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 860, '2026-10-20T04:30:00.000Z'::timestamptz, '2026-10-18T04:30:00.000Z'::timestamptz, '2026-10-20T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000011'::uuid, '00000002-0000-4000-8000-000000000007'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000011'::uuid, 'en'::content_language, 'Tamil Nadu sample libraries share one story crate', 'Four fictional reading rooms in Tamil Nadu passed a crate of bilingual picture books and logged which titles left the shelf.', 'The crate carried a paper passport. Each room stamped the date and added one sentence from a child about the cover, not a review score.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000011'::uuid, 'hi'::content_language, 'तमिलनाडु के नमूना पुस्तकालयों ने एक कहानी पेटी बाँटी', 'तमिलनाडु के चार काल्पनिक वाचनालयों ने द्विभाषी चित्र पुस्तकों की एक पेटी आगे बढ़ाई और दर्ज किया कि कौन से शीर्षक शेल्फ से उठे।', 'पेटी के साथ कागज़ का पासपोर्ट था। हर कमरे ने तारीख की मुहर लगाई और कवर के बारे में एक बच्चे का एक वाक्य जोड़ा, कोई समीक्षा अंक नहीं।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000012'::uuid, 'published'::article_status, 'state'::coverage_level, 'Gujarat', 'Rajkot', 'राजकोट', NULL, '00000002-0000-4000-8000-000000000009'::uuid, ARRAY['gujarat', 'water', 'farms']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Gujarat sample workshop maps a drip-line with string', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: गुजरात के नमूना कार्यशाला में धागे से ड्रिप लाइन बनी', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 730, '2026-10-21T04:30:00.000Z'::timestamptz, '2026-10-19T04:30:00.000Z'::timestamptz, '2026-10-21T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000012'::uuid, '00000002-0000-4000-8000-000000000009'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000012'::uuid, 'en'::content_language, 'Gujarat sample workshop maps a drip-line with string', 'Farm-club members in a fictional Rajkot workshop laid string across a courtyard to rehearse a drip-line path.', 'They marked taps with bottle caps and refused to connect a hose. The point was to see whether a path crossed the walking line used by elders at dusk.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000012'::uuid, 'hi'::content_language, 'गुजरात के नमूना कार्यशाला में धागे से ड्रिप लाइन बनी', 'काल्पनिक राजकोट कार्यशाला में कृषि क्लब के सदस्यों ने आँगन में धागा बिछाकर ड्रिप लाइन का मार्ग दोहराया।', 'उन्होंने नल को बोतल के ढक्कनों से चिह्नित किया और पाइप नहीं जोड़ा। उद्देश्य यह देखना था कि मार्ग उस पैदल लाइन को काटता है या नहीं जिस पर बुजुर्ग शाम को चलते हैं।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000013'::uuid, 'published'::article_status, 'state'::coverage_level, 'West Bengal', 'Kolkata', 'कोलकाता', NULL, '00000002-0000-4000-8000-000000000010'::uuid, ARRAY['bengal', 'river', 'study']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Bengal sample class sketches a riverbank cross-section', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: बंगाल की नमूना कक्षा ने नदी किनारे का क्रॉस-सेक्शन बनाया', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 690, '2026-10-19T04:30:00.000Z'::timestamptz, '2026-10-17T04:30:00.000Z'::timestamptz, '2026-10-19T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000013'::uuid, '00000002-0000-4000-8000-000000000010'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000013'::uuid, 'en'::content_language, 'Bengal sample class sketches a riverbank cross-section', 'Geography students in a fictional Kolkata class drew a riverbank cross-section from a sand tray and a week of imagined rain cards.', 'The tray used two colours of sand and a blue ribbon for the channel. Students predicted which card would move the ribbon and then checked their guess.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000013'::uuid, 'hi'::content_language, 'बंगाल की नमूना कक्षा ने नदी किनारे का क्रॉस-सेक्शन बनाया', 'काल्पनिक कोलकाता कक्षा के भूगोल विद्यार्थियों ने रेत की ट्रे और एक सप्ताह के काल्पनिक वर्षा कार्ड से नदी किनारे का क्रॉस-सेक्शन बनाया।', 'ट्रे में दो रंग की रेत और नहर के लिए नीली रिबन थी। विद्यार्थियों ने अनुमान लगाया कि कौन सा कार्ड रिबन हटाएगा, फिर अपना अनुमान जाँचा।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000014'::uuid, 'published'::article_status, 'state'::coverage_level, 'Karnataka', 'Bengaluru', 'बेंगलुरु', NULL, '00000002-0000-4000-8000-000000000003'::uuid, ARRAY['karnataka', 'athletics', 'camp']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1531415074968-036ba1b575da?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Karnataka sample camp times a friendly relay', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: कर्नाटक के नमूना शिविर ने दोस्ताना रिले का समय लिया', '[]'::jsonb, false, false, 30, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 2740, '2026-10-24T04:30:00.000Z'::timestamptz, '2026-10-22T04:30:00.000Z'::timestamptz, '2026-10-24T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000014'::uuid, '00000002-0000-4000-8000-000000000003'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000014'::uuid, 'en'::content_language, 'Karnataka sample camp times a friendly relay', 'A fictional athletics camp near Bengaluru timed a mixed relay and a water break, then posted the sheets on a classroom wall.', 'Coaches in the scenario rotated lanes so no group kept the inside curve. The fastest sheet was applauded and then taken down so it would not be mistaken for a state ranking.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000014'::uuid, 'hi'::content_language, 'कर्नाटक के नमूना शिविर ने दोस्ताना रिले का समय लिया', 'बेंगलुरु के पास एक काल्पनिक एथलेटिक्स शिविर ने मिश्रित रिले और पानी के विराम का समय लिया, फिर पन्ने कक्षा की दीवार पर लगाए।', 'दृश्य के कोचों ने लेन बदलीं ताकि कोई समूह भीतरी मोड़ अपने पास न रखे। सबसे तेज़ पन्ने की ताली बजी और फिर उसे हटा दिया गया ताकि उसे राज्य रैंकिंग न समझा जाए।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000015'::uuid, 'published'::article_status, 'national'::coverage_level, 'Delhi', 'New Delhi', 'नई दिल्ली', NULL, '00000002-0000-4000-8000-000000000010'::uuid, ARRAY['delhi', 'science', 'exhibit']::text[], '00000001-0000-4000-8000-000000000002'::uuid, 'https://images.unsplash.com/photo-1532375810709-75b1da00537c?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Sample science exhibit opens a paper planet corner', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: नमूना विज्ञान प्रदर्शनी में कागज़ के ग्रह का कोना खुला', '[{"url":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=1600&h=900&q=80","altEn":"Sample gallery image 1 for Sample science exhibit opens a paper planet corner","altHi":"नमूना गैलरी चित्र 1"},{"url":"https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1400&h=900&q=80","altEn":"Sample gallery image 2 for Sample science exhibit opens a paper planet corner","altHi":"नमूना गैलरी चित्र 2"}]'::jsonb, true, true, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 4120, '2026-10-26T04:30:00.000Z'::timestamptz, '2026-10-24T04:30:00.000Z'::timestamptz, '2026-10-26T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000015'::uuid, '00000002-0000-4000-8000-000000000010'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000015'::uuid, 'en'::content_language, 'Sample science exhibit opens a paper planet corner', 'A fictional national science corner in Delhi invited visitors to label paper planets and a hand-crank orrery built from cardboard.', 'The exhibit kept the lights low so a torch could stand in for the sun. Volunteers asked children to say one careful sentence about scale instead of memorising a slogan.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000015'::uuid, 'hi'::content_language, 'नमूना विज्ञान प्रदर्शनी में कागज़ के ग्रह का कोना खुला', 'दिल्ली के एक काल्पनिक राष्ट्रीय विज्ञान कोने में आगंतुकों ने कागज़ के ग्रहों और गत्ते से बने हैंड-क्रैंक मॉडल पर नाम लिखे।', 'प्रदर्शनी की रोशनी कम रखी गई ताकि टॉर्च सूरज का काम करे। स्वयंसेवकों ने बच्चों से नारा याद करने के बजाय पैमाने के बारे में एक सावधान वाक्य कहने को कहा।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000016'::uuid, 'published'::article_status, 'national'::coverage_level, NULL, NULL, NULL, NULL, '00000002-0000-4000-8000-000000000004'::uuid, ARRAY['rail', 'timetable', 'technology']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Sample rail desk builds a paper timetable sandbox', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: नमूना रेल डेस्क ने कागज़ की समय-सारणी बनाई', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 2310, '2026-10-24T04:30:00.000Z'::timestamptz, '2026-10-22T04:30:00.000Z'::timestamptz, '2026-10-24T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000016'::uuid, '00000002-0000-4000-8000-000000000004'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000016'::uuid, 'en'::content_language, 'Sample rail desk builds a paper timetable sandbox', 'A fictional national desk arranged coloured strings for three sample trains and tested what happened when one string was delayed by four minutes.', 'Planners in the exercise moved sticky notes, not real crews. A conflict appeared where two strings wanted the same platform card, so the group added a passing loop made of tape.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000016'::uuid, 'hi'::content_language, 'नमूना रेल डेस्क ने कागज़ की समय-सारणी बनाई', 'एक काल्पनिक राष्ट्रीय डेस्क ने तीन नमूना रेलगाड़ियों के लिए रंगीन धागे सजाए और देखा कि एक धागा चार मिनट देर से चले तो क्या होता है।', 'अभ्यास के योजनाकारों ने असली कर्मचारियों को नहीं, चिपकने वाले नोट हिलाए। दो धागे एक ही प्लेटफ़ॉर्म कार्ड चाहते थे, इसलिए समूह ने टेप का पासिंग लूप जोड़ा।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000017'::uuid, 'published'::article_status, 'national'::coverage_level, NULL, NULL, NULL, NULL, '00000002-0000-4000-8000-000000000006'::uuid, ARRAY['monsoon', 'weather', 'briefing']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1495020689067-958852a7765e?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Sample monsoon desk runs a briefing with cue cards', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: नमूना मानसून डेस्क ने संकेत कार्डों से ब्रीफिंग की', '[]'::jsonb, false, true, 10, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 3860, '2026-10-26T04:30:00.000Z'::timestamptz, '2026-10-24T04:30:00.000Z'::timestamptz, '2026-10-26T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000017'::uuid, '00000002-0000-4000-8000-000000000006'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000017'::uuid, 'en'::content_language, 'Sample monsoon desk runs a briefing with cue cards', 'The fictional national weather corner stacked cue cards for rain, drains, and school buses, then practised reading them without calling the scene a forecast.', 'Each card had a large SAMPLE stamp. Readers had to point to the stamp before speaking so listeners would hear the difference between a drill and a warning.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000017'::uuid, 'hi'::content_language, 'नमूना मानसून डेस्क ने संकेत कार्डों से ब्रीफिंग की', 'काल्पनिक राष्ट्रीय मौसम कोने ने बारिश, नालियों और स्कूल बसों के संकेत कार्ड सजाए और उन्हें पूर्वानुमान कहे बिना पढ़ने का अभ्यास किया।', 'हर कार्ड पर बड़ा SAMPLE मुहर था। बोलने से पहले पाठक को मुहर दिखानी होती थी ताकि श्रोता अभ्यास और चेतावनी का अंतर सुन सकें।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000018'::uuid, 'published'::article_status, 'national'::coverage_level, NULL, NULL, NULL, NULL, '00000002-0000-4000-8000-000000000003'::uuid, ARRAY['cricket', 'academy', 'friendly']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1531415074968-036ba1b575da?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Sample cricket academy posts a friendly series sheet', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: नमूना क्रिकेट अकादमी ने दोस्ताना श्रृंखला की सूची लगाई', '[]'::jsonb, true, false, 20, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 4680, '2026-10-25T04:30:00.000Z'::timestamptz, '2026-10-23T04:30:00.000Z'::timestamptz, '2026-10-25T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000018'::uuid, '00000002-0000-4000-8000-000000000003'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000018'::uuid, 'en'::content_language, 'Sample cricket academy posts a friendly series sheet', 'A fictional academy pinned a three-match friendly sheet, with equal overs for the bench and no claim of a national selection.', 'Scorers used pencils. A rule at the top of the sheet said the numbers would be erased after the demo so they could not be quoted as a record.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000018'::uuid, 'hi'::content_language, 'नमूना क्रिकेट अकादमी ने दोस्ताना श्रृंखला की सूची लगाई', 'एक काल्पनिक अकादमी ने तीन मैचों की दोस्ताना सूची लगाई, जिसमें बेंच के लिए बराबर ओवर थे और राष्ट्रीय चयन का कोई दावा नहीं था।', 'स्कोररों ने पेंसिल इस्तेमाल की। सूची के ऊपर नियम था कि डेमो के बाद अंक मिटा दिए जाएँगे ताकि उन्हें रिकॉर्ड की तरह उद्धृत न किया जा सके।
INSERT INTO articles (id, status, coverage, state, city, city_hi, locality, category_id, tags, author_id, cover_image_url, cover_image_alt_en, cover_image_alt_hi, gallery, featured, breaking, trending_boost, source_name, source_url, correction_note_en, correction_note_hi, corrected_at, rejection_reason, view_count, published_at, created_at, updated_at) VALUES ('00000003-0000-4000-8000-000000000019'::uuid, 'published'::article_status, 'national'::coverage_level, NULL, NULL, NULL, NULL, '00000002-0000-4000-8000-000000000005'::uuid, ARRAY['music', 'archive', 'folk']::text[], '00000001-0000-4000-8000-000000000003'::uuid, 'https://images.unsplash.com/photo-1587474260584-136574528ed5?auto=format&fit=crop&w=1400&h=900&q=80', 'Sample photo used with the demonstration story: Sample archive labels a folk chorus on cassette cards', 'प्रदर्शन कथा के साथ लगी नमूना तस्वीर: नमूना संग्रह ने लोक स्वर को कैसेट कार्डों पर लिखा', '[]'::jsonb, false, false, 0, 'News India Sample Desk', NULL, NULL, NULL, NULL, NULL, 1010, '2026-10-18T04:30:00.000Z'::timestamptz, '2026-10-16T04:30:00.000Z'::timestamptz, '2026-10-18T04:30:00.000Z'::timestamptz);
INSERT INTO article_categories (article_id, category_id) VALUES ('00000003-0000-4000-8000-000000000019'::uuid, '00000002-0000-4000-8000-000000000005'::uuid);
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000019'::uuid, 'en'::content_language, 'Sample archive labels a folk chorus on cassette cards', 'A fictional culture desk labelled cassette cards for a classroom chorus, noting the language of each verse and who taught the clap.', 'No field recording was made. Students hummed eight bars and stopped when the card was full. The point was the label, not a release.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000019'::uuid, 'hi'::content_language, 'नमूना संग्रह ने लोक स्वर को कैसेट कार्डों पर लिखा', 'एक काल्पनिक संस्कृति डेस्क ने कक्षा गायन के कैसेट कार्डों पर हर पद की भाषा और ताली सिखाने वाले का नाम लिखा।', 'कोई फील्ड रिकॉर्डिंग नहीं हुई। विद्यार्थियों ने आठ बार गुनगुनाए और कार्ड भरते ही रुके। उद्देश्य लेबल था, कोई रिलीज़ नहीं।
