INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000020'::uuid, 'en'::content_language, 'Sample coding fair debugs a library-card bot', 'Students at a fictional national fair debugged a tiny bot that sorted paper library cards into “story” and “science” trays.', 'The bot was a cardboard box with a hand crank. When it dropped a card in the wrong tray, the team wrote the mistake on the side instead of hiding it.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000020'::uuid, 'hi'::content_language, 'नमूना कोडिंग मेले में लाइब्रेरी-कार्ड बॉट सुधरा', 'एक काल्पनिक राष्ट्रीय मेले में विद्यार्थियों ने एक छोटे बॉट को सुधारा जो कागज़ी लाइब्रेरी कार्ड को “कथा” और “विज्ञान” ट्रे में बाँटता था।', 'बॉट हैंड क्रैंक वाला गत्ते का डिब्बा था। जब उसने कार्ड गलत ट्रे में डाला, टीम ने गलती को छिपाने के बजाय किनारे पर लिख दिया।
