INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000021'::uuid, 'en'::content_language, 'Sample star club holds a torch-only telescope night', 'A fictional club in Leh practised a night session with a cardboard tube and a star chart, keeping the room lights off except for one red torch.', 'Participants had to find three labelled dots on the chart before they could describe a constellation in their own words. Nobody claimed a discovery.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000021'::uuid, 'hi'::content_language, 'नमूना तारा क्लब ने केवल टॉर्च वाली दूरबीन रात रखी', 'लेह के एक काल्पनिक क्लब ने गत्ते की नली और तारा मानचित्र के साथ रात्रि सत्र का अभ्यास किया। कमरे में केवल एक लाल टॉर्च जली रही।', 'प्रतिभागियों को अपने शब्दों में तारामंडल बताने से पहले मानचित्र पर तीन चिह्नित बिंदु ढूँढने थे। किसी ने खोज का दावा नहीं किया।
