INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000027'::uuid, 'hi'::content_language, 'जमा: मुंबई के नमूना बस शेल्टर का रेखाचित्र', 'एक जमा मसौदा कागज़ के मार्ग मानचित्र और छायादार बेंच वाले काल्पनिक बस शेल्टर का रेखाचित्र बताता है।', 'रेखाचित्र पूछता है कि खड़ा पाठक बारिश में मार्ग कार्ड देख सकता है या नहीं। यह संपादकीय समीक्षा की प्रतीक्षा में है।
