INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000028'::uuid, 'en'::content_language, 'Submitted: Thrissur sample art-festival plan', 'A state culture story about a fictional one-room art festival is in the submitted queue.', 'The plan lists four walls: textile, photo, school poster, and a quiet chair. The reporter has asked for review.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000028'::uuid, 'hi'::content_language, 'जमा: त्रिशूर की नमूना कला-उत्सव योजना', 'एक कमरे के काल्पनिक कला उत्सव पर राज्य संस्कृति कथा जमा कतार में है।', 'योजना में चार दीवारें हैं: कपड़ा, फ़ोटो, विद्यालय पोस्टर और एक शांत कुर्सी। रिपोर्टर ने समीक्षा माँगी है।
