INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000029'::uuid, 'hi'::content_language, 'स्वीकृत नमूना: वाराणसी की कक्षा नदी योजना', 'संपादकों ने नदी किनारे की सफाई की एक काल्पनिक कक्षा योजना स्वीकार कर ली है, पर वह अभी प्रकाशित नहीं हुई।', 'स्वीकृत पाठ में दस्ताने, गिनती पन्ना और पंद्रह मिनट की सीमा है। प्रकाशन अलग चरण है।
