INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000030'::uuid, 'hi'::content_language, 'स्वीकृत नमूना: राष्ट्रीय प्रश्नोत्तरी रात की पटकथा', 'काल्पनिक प्रश्नोत्तरी रात की स्वीकृत किंतु अप्रकाशित नमूना पटकथा संपादकों के पास है।', 'तीसरा दौर केवल डेमो कैप्शन वाली चित्र पारी है। जब संपादक चाहे, पटकथा प्रकाशन के लिए तैयार है।
