INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000031'::uuid, 'hi'::content_language, 'अस्वीकृत नमूना: बिना नाम का गलियारा नोट', 'संपादकों ने इस काल्पनिक राजनीतिक नोट को अस्वीकार किया क्योंकि नमूना स्रोत बिना नाम का था।', 'मूल शब्दों ने एक गलियारे की टिप्पणी दोहराई थी, जिसे डेमो के अंदर भी कोई व्यक्ति अपने नाम से नहीं कहना चाहता था।
