INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000032'::uuid, 'en'::content_language, 'Rejected sample: unverified friendly scorecard', 'A fictional scorecard was rejected because the runs did not match the sample scorer sheet.', 'The sheet showed 42 runs and the story said 142. Editors sent it back rather than publish a demo error as fact.
INSERT INTO article_translations (article_id, language, title, summary, body, slug, seo_title, seo_description) VALUES ('00000003-0000-4000-8000-000000000032'::uuid, 'hi'::content_language, 'अस्वीकृत नमूना: असत्यापित दोस्ताना स्कोरकार्ड', 'एक काल्पनिक स्कोरकार्ड अस्वीकार हुआ क्योंकि रन नमूना स्कोरर शीट से नहीं मिलते थे।', 'शीट पर 42 रन थे और कथा में 142 लिखे थे। संपादकों ने डेमो की गलती को तथ्य की तरह छापने के बजाय इसे लौटा दिया।
